import { randomUUID } from 'node:crypto';
import type { DatabaseSync } from 'node:sqlite';
import { transaction } from './db.ts';

export const DEFAULT_STEPS = 5;
export const MIN_STEPS = 1;
export const MAX_STEPS = 20;
export const MAX_FAIL_ATTEMPTS = 5;
export const MAX_INPUT_LENGTH = 1000;
export const IDEMPOTENCY_KEY_PATTERN = /^[A-Za-z0-9_-]{1,128}$/;

/** Processing attempts allowed in total before a job is marked failed. */
export const MAX_ATTEMPTS = 3;
/** Delay before a failed attempt is retried. */
export const RETRY_DELAY_MS = 500;
/** Time each processing step takes. */
export const STEP_MS = 100;
/** Worker heartbeat interval, and the age after which the worker counts as down. */
export const HEARTBEAT_MS = 1000;
export const HEARTBEAT_STALE_MS = 3000;

export type JobStatus = 'queued' | 'running' | 'completed' | 'failed';

/** A row of the `jobs` table, as SQLite returns it. */
export interface JobRow {
  seq: number;
  id: string;
  status: JobStatus;
  input: string;
  steps: number;
  fail_attempts: number;
  attempts: number;
  progress_completed: number;
  result_output: string | null;
  error: string | null;
  run_at: number;
  created_at: string;
  updated_at: string;
}

/** The public job shape returned by the API. */
export interface Job {
  id: string;
  status: JobStatus;
  input: string;
  steps: number;
  failAttempts: number;
  attempts: number;
  progress: { completed: number; total: number };
  result: { output: string } | null;
  error: string | null;
  createdAt: string;
  updatedAt: string;
}

export interface FieldError {
  field: string;
  message: string;
}

export interface Payload {
  input: string;
  steps: number;
  failAttempts: number;
}

export function toJob(r: JobRow): Job {
  return {
    id: r.id,
    status: r.status,
    input: r.input,
    steps: r.steps,
    failAttempts: r.fail_attempts,
    attempts: r.attempts,
    progress: { completed: r.progress_completed, total: r.steps },
    result: r.status === 'completed' && r.result_output !== null ? { output: r.result_output } : null,
    error: r.status === 'failed' ? r.error : null,
    createdAt: r.created_at,
    updatedAt: r.updated_at,
  };
}

function integerField(obj: Record<string, unknown>, name: string, min: number, max: number, fallback: number, fields: FieldError[]): number {
  if (!Object.hasOwn(obj, name)) return fallback;
  const v = obj[name];
  if (typeof v !== 'number' || !Number.isInteger(v)) {
    fields.push({ field: name, message: 'must be an integer' });
    return fallback;
  }
  if (v < min || v > max) {
    fields.push({ field: name, message: `must be between ${min} and ${max}` });
    return fallback;
  }
  return v;
}

/** Validates a parsed request body. Returns the payload with defaults applied, or the offending fields. */
export function parseSubmission(raw: unknown): { payload: Payload } | { fields: FieldError[] } {
  if (typeof raw !== 'object' || raw === null || Array.isArray(raw)) {
    return { fields: [{ field: 'body', message: 'must be a JSON object' }] };
  }
  const obj = raw as Record<string, unknown>;
  const fields: FieldError[] = [];
  const allowed = new Set(['input', 'steps', 'failAttempts']);
  for (const key of Object.keys(obj)) {
    if (!allowed.has(key)) fields.push({ field: key, message: 'is not a known field' });
  }

  let input = '';
  if (!Object.hasOwn(obj, 'input')) {
    fields.push({ field: 'input', message: 'is required' });
  } else if (typeof obj.input !== 'string') {
    fields.push({ field: 'input', message: 'must be a string' });
  } else if (obj.input.length < 1 || obj.input.length > MAX_INPUT_LENGTH) {
    fields.push({ field: 'input', message: `must be 1 to ${MAX_INPUT_LENGTH} characters` });
  } else if (obj.input.trim() === '') {
    fields.push({ field: 'input', message: 'must not be only whitespace' });
  } else {
    input = obj.input;
  }

  const steps = integerField(obj, 'steps', MIN_STEPS, MAX_STEPS, DEFAULT_STEPS, fields);
  const failAttempts = integerField(obj, 'failAttempts', 0, MAX_FAIL_ATTEMPTS, 0, fields);
  if (fields.length > 0) return { fields };
  return { payload: { input, steps, failAttempts } };
}

export function getJobRow(db: DatabaseSync, id: string): JobRow | undefined {
  return db.prepare('SELECT * FROM jobs WHERE id = ?').get(id) as unknown as JobRow | undefined;
}

export function listJobRows(db: DatabaseSync): JobRow[] {
  return db.prepare('SELECT * FROM jobs ORDER BY seq DESC').all() as unknown as JobRow[];
}

export type SubmitResult = { kind: 'created' | 'replayed'; job: Job } | { kind: 'conflict' };

/**
 * Creates a job, or, when an idempotency key is given, replays the job created with that key.
 * The check and the insert share one transaction, so a key never produces two jobs.
 */
export function submitJob(db: DatabaseSync, payload: Payload, key: string | undefined): SubmitResult {
  // The payload with defaults applied, in a fixed order, is the thing compared for idempotency.
  const fingerprint = JSON.stringify([payload.input, payload.steps, payload.failAttempts]);
  return transaction(db, (): SubmitResult => {
    if (key !== undefined) {
      const existing = db.prepare('SELECT payload, job_id FROM idempotency_keys WHERE key = ?').get(key) as
        | { payload: string; job_id: string }
        | undefined;
      if (existing) {
        if (existing.payload !== fingerprint) return { kind: 'conflict' };
        const row = getJobRow(db, existing.job_id);
        if (!row) throw new Error(`idempotency key ${key} refers to missing job ${existing.job_id}`);
        return { kind: 'replayed', job: toJob(row) };
      }
    }
    const id = randomUUID();
    const now = new Date().toISOString();
    db.prepare(
      `INSERT INTO jobs (id, status, input, steps, fail_attempts, attempts, progress_completed, run_at, created_at, updated_at)
       VALUES (?, 'queued', ?, ?, ?, 0, 0, ?, ?, ?)`,
    ).run(id, payload.input, payload.steps, payload.failAttempts, Date.now(), now, now);
    if (key !== undefined) {
      db.prepare('INSERT INTO idempotency_keys (key, payload, job_id) VALUES (?, ?, ?)').run(key, fingerprint, id);
    }
    const row = getJobRow(db, id);
    if (!row) throw new Error(`job ${id} missing after insert`);
    return { kind: 'created', job: toJob(row) };
  });
}

