import { createServer, type IncomingMessage, type ServerResponse } from 'node:http';
import { readFileSync } from 'node:fs';
import { openDatabase } from './db.ts';
import {
  HEARTBEAT_STALE_MS,
  IDEMPOTENCY_KEY_PATTERN,
  getJobRow,
  listJobRows,
  parseSubmission,
  submitJob,
  toJob,
  type FieldError,
} from './jobs.ts';

const MAX_BODY_BYTES = 64 * 1024;

const db = openDatabase();
const uiHtml = readFileSync(new URL('../ui/index.html', import.meta.url), 'utf8');
const port = Number(process.env.PORT || 3000);

function send(res: ServerResponse, status: number, body: unknown): void {
  res.writeHead(status, { 'content-type': 'application/json; charset=utf-8' });
  res.end(JSON.stringify(body));
}

function sendError(res: ServerResponse, status: number, code: string, message: string, fields?: FieldError[]): void {
  send(res, status, { error: { code, message, ...(fields ? { fields } : {}) } });
}

function methodNotAllowed(res: ServerResponse, allowed: string[]): void {
  res.setHeader('allow', allowed.join(', '));
  sendError(res, 405, 'method_not_allowed', `Method not allowed. Allowed: ${allowed.join(', ')}.`);
}

function workerUp(): boolean {
  const row = db.prepare("SELECT at FROM worker_heartbeat WHERE name = 'worker'").get() as unknown as { at: number } | undefined;
  return row !== undefined && Date.now() - row.at <= HEARTBEAT_STALE_MS;
}

/** Reads the request body. Resolves to undefined when it exceeds MAX_BODY_BYTES. */
function readBody(req: IncomingMessage): Promise<string | undefined> {
  return new Promise((resolve, reject) => {
    const chunks: Buffer[] = [];
    let size = 0;
    let tooLarge = false;
    req.on('data', (chunk: Buffer) => {
      size += chunk.length;
      if (size > MAX_BODY_BYTES) tooLarge = true;
      else chunks.push(chunk);
    });
    req.on('end', () => resolve(tooLarge ? undefined : Buffer.concat(chunks).toString('utf8')));
    req.on('error', reject);
  });
}

async function handleCreate(req: IncomingMessage, res: ServerResponse): Promise<void> {
  const rawBody = await readBody(req);
  const fields: FieldError[] = [];

  const key = req.headers['idempotency-key'];
  if (key !== undefined && !IDEMPOTENCY_KEY_PATTERN.test(key)) {
    fields.push({ field: 'Idempotency-Key', message: 'must match ^[A-Za-z0-9_-]{1,128}$' });
  }

  const mediaType = (req.headers['content-type'] ?? '').split(';')[0]!.trim().toLowerCase();
  let payload: ReturnType<typeof parseSubmission> | undefined;
  if (mediaType !== 'application/json') {
    fields.push({ field: 'body', message: 'Content-Type must be application/json' });
  } else if (rawBody === undefined) {
    fields.push({ field: 'body', message: `body must be at most ${MAX_BODY_BYTES} bytes` });
  } else {
    let parsed: unknown;
    try {
      parsed = JSON.parse(rawBody);
      payload = parseSubmission(parsed);
    } catch {
      fields.push({ field: 'body', message: 'must be valid JSON' });
    }
    if (payload && 'fields' in payload) fields.push(...payload.fields);
  }

  if (fields.length > 0 || !payload || !('payload' in payload)) {
    return sendError(res, 400, 'invalid_request', 'The submission is invalid.', fields);
  }

  const result = submitJob(db, payload.payload, key);
  if (result.kind === 'conflict') {
    return sendError(res, 409, 'idempotency_conflict', 'This Idempotency-Key was already used with a different payload.');
  }
  send(res, result.kind === 'created' ? 201 : 200, toJob(getJobRowOrThrow(result.job.id)));
}

function getJobRowOrThrow(id: string) {
  const row = getJobRow(db, id);
  if (!row) throw new Error(`job ${id} missing`);
  return row;
}

async function handle(req: IncomingMessage, res: ServerResponse): Promise<void> {
  const method = req.method ?? 'GET';
  const { pathname } = new URL(req.url ?? '/', 'http://localhost');

  if (pathname === '/health') {
    if (method !== 'GET') return methodNotAllowed(res, ['GET']);
    return send(res, 200, { status: 'ok', worker: workerUp() ? 'up' : 'down' });
  }
  if (pathname === '/') {
    if (method !== 'GET') return methodNotAllowed(res, ['GET']);
    res.writeHead(200, { 'content-type': 'text/html; charset=utf-8' });
    res.end(uiHtml);
    return;
  }
  if (pathname === '/api/jobs') {
    if (method === 'GET') return send(res, 200, { jobs: listJobRows(db).map(toJob) });
    if (method === 'POST') return handleCreate(req, res);
    return methodNotAllowed(res, ['GET', 'POST']);
  }
  const match = /^\/api\/jobs\/([^/]+)$/.exec(pathname);
  if (match) {
    if (method !== 'GET') return methodNotAllowed(res, ['GET']);
    const row = getJobRow(db, match[1]!);
    if (!row) return sendError(res, 404, 'not_found', 'No such job.');
    return send(res, 200, toJob(row));
  }
  sendError(res, 404, 'not_found', 'No such route.');
}

const server = createServer((req, res) => {
  handle(req, res).catch((e: unknown) => {
    console.error('request failed:', e);
    if (!res.headersSent) sendError(res, 500, 'internal_error', 'Unexpected server error.');
    else res.end();
  });
});

let shuttingDown = false;
function shutdown(): void {
  if (shuttingDown) return;
  shuttingDown = true;
  server.close(() => {
    db.close();
    process.exit(0);
  });
  server.closeAllConnections();
}
process.on('SIGTERM', shutdown);
process.on('SIGINT', shutdown);

server.listen(port, () => console.log(`server listening on ${port}`));

