import type { DatabaseSync } from 'node:sqlite';
import { setTimeout as sleep } from 'node:timers/promises';
import { openDatabase, transaction } from './db.ts';
import { HEARTBEAT_MS, MAX_ATTEMPTS, RETRY_DELAY_MS, STEP_MS, type JobRow } from './jobs.ts';

/** How often an idle worker checks the queue. Pickup must happen within 1 s. */
const POLL_MS = 200;

const db = openDatabase();
let stopping = false;
for (const signal of ['SIGINT', 'SIGTERM'] as const) {
  process.on(signal, () => {
    stopping = true;
  });
}

function heartbeat(): void {
  db.prepare(
    `INSERT INTO worker_heartbeat (name, at) VALUES ('worker', ?)
     ON CONFLICT (name) DO UPDATE SET at = excluded.at`,
  ).run(Date.now());
}

/** Puts jobs left "running" by a dead worker back in the queue. Only one worker runs at a time. */
function requeueRunning(): void {
  db.prepare("UPDATE jobs SET status = 'queued', progress_completed = 0, run_at = ?, updated_at = ? WHERE status = 'running'").run(
    Date.now(),
    new Date().toISOString(),
  );
}

/** Atomically takes the oldest queued job that is due, and marks a new attempt on it. */
function claimNext(): JobRow | undefined {
  return transaction(db, () => {
    const row = db
      .prepare("SELECT * FROM jobs WHERE status = 'queued' AND run_at <= ? ORDER BY seq LIMIT 1")
      .get(Date.now()) as unknown as JobRow | undefined;
    if (!row) return undefined;
    db.prepare("UPDATE jobs SET status = 'running', attempts = attempts + 1, progress_completed = 0, updated_at = ? WHERE id = ?").run(
      new Date().toISOString(),
      row.id,
    );
    return { ...row, status: 'running', attempts: row.attempts + 1, progress_completed: 0 };
  });
}

/** Ends an attempt that failed transiently: retry later, or mark the job failed after the last attempt. */
function failAttempt(job: JobRow): void {
  transaction(db, () => {
    const now = new Date().toISOString();
    if (job.attempts >= MAX_ATTEMPTS) {
      db.prepare(
        "UPDATE jobs SET status = 'failed', error = 'transient failure', result_output = NULL, progress_completed = 0, updated_at = ? WHERE id = ?",
      ).run(now, job.id);
    } else {
      db.prepare("UPDATE jobs SET status = 'queued', progress_completed = 0, run_at = ?, updated_at = ? WHERE id = ?").run(
        Date.now() + RETRY_DELAY_MS,
        now,
        job.id,
      );
    }
  });
}

function completeJob(job: JobRow): void {
  db.prepare(
